def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    c_opp = opp.count('C')
    d_opp = n - c_opp
    coop_rate = c_opp / n

    if d_opp == 0:
        # Against a pure cooperator, defect only in the last few rounds,
        # otherwise keep cooperating to avoid destabilizing.
        if 100 - n <= 2:
            return 'D'
        return 'C'
    if c_opp == 0:
        return 'D'

    # endgame handling
    remaining = 100 - n
    if remaining <= 2:
        if coop_rate > 0.5:
            return 'D'
        return 'D' if d_opp > c_opp else 'C'

    # suffix streaks
    streak_d = 0
    i = n - 1
    while i >= 0 and opp[i] == 'D':
        streak_d += 1
        i -= 1

    streak_c = 0
    i = n - 1
    while i >= 0 and opp[i] == 'C':
        streak_c += 1
        i -= 1

    # Identify TFT-like opponents by testing correlation between our previous
    # action and their current action.
    if n >= 8:
        match_prev = 0
        for i in range(1, n):
            if opp[i] == me[i - 1]:
                match_prev += 1
        tft_score = match_prev / (n - 1)
    else:
        tft_score = 0.0

    # Identify opponents that punish our defections:如果他们总是在我们D后D
    punish_after_my_d = 0
    my_d_count = 0
    for i in range(n - 1):
        if me[i] == 'D':
            my_d_count += 1
            if opp[i + 1] == 'D':
                punish_after_my_d += 1

    # Reward after our cooperation
    reward_after_my_c = 0
    my_c_count = 0
    for i in range(n - 1):
        if me[i] == 'C':
            my_c_count += 1
            if opp[i + 1] == 'C':
                reward_after_my_c += 1

    # Cooperation-friendly, retaliatory core.
    if streak_d >= 2:
        # If opponent is TFT-like and we caused the defection, return to C.
        if tft_score >= 0.6 and n >= 2 and me[-1] == 'D':
            return 'C'
        # Otherwise punish.
        return 'D'

    if streak_d == 1:
        # Single defection: forgive if opponent otherwise cooperative and
        # we may have triggered it.
        if coop_rate > 0.75 and streak_c >= 2:
            return 'C'
        if n >= 3 and opp[-2] == 'C' and opp[-3] == 'C' and rng.random() < 0.6:
            return 'C'
        # If we defected last round, they may be retaliating; return to C.
        if me[-1] == 'D':
            return 'C'
        return 'D'

    # Opponent last cooperated.
    # If we defected last round, returning to C is usually best against TFT.
    if me[-1] == 'D':
        return 'C'

    # Exploit detection: if opponent rewards our defections while cooperating,
    # they may be a pushover. Defect more.
    if my_d_count >= 2 and reward_after_my_c >= my_c_count * 0.9 and coop_rate > 0.6:
        if rng.random() < 0.5:
            return 'D'

    # If opponent is very cooperative and rarely retaliates, exploit moderately.
    if coop_rate >= 0.85:
        if n >= 90:
            return 'D'
        if n % 11 == 0:
            return 'D'
        return 'C'

    # If opponent punishes our D almost always, avoid defecting.
    if my_d_count >= 3 and punish_after_my_d >= my_d_count * 0.85:
        return 'C'

    # Steady cooperative default with light probing.
    if n >= 20 and n % 19 == 0 and coop_rate > 0.6:
        return 'D'

    if coop_rate >= 0.55:
        return 'C'

    # Moderately cooperative: defect sometimes.
    if rng.random() < 0.25:
        return 'D'
    return 'C'
